// Export Copilot VENTESTOCKFLOW (~11 Mo, 35 jours) : trop gros pour un seul appel.
// On le découpe en tranches de 7 jours ; chaque tranche remplace ses jours dans le portail.
const sortie = [];
const items = $input.all();
const champ = (ligne, index) => {           // n-ième cellule d'une ligne CSV (guillemets gérés)
  let cour = '', entre = false, n = 0;
  for (let i = 0; i < ligne.length; i++) {
    const ch = ligne[i];
    if (ch === '"') { if (entre && ligne[i + 1] === '"') { cour += '"'; i++; } else entre = !entre; }
    else if (ch === ',' && !entre) { if (n === index) return cour; n++; cour = ''; }
    else cour += ch;
  }
  return n === index ? cour : '';
};
for (let k = 0; k < items.length; k++) {
  const item = items[k];
  const cles = Object.keys(item.binary || {});
  const cle = cles.find(c => /VENTESTOCKFLOW.*\.csv$/i.test(item.binary[c].fileName || ''));
  if (!cle) continue;
  const texte = (await this.helpers.getBinaryDataBuffer(k, cle)).toString('utf8').replace(/^﻿/, '');
  const lignes = texte.split(/\r?\n/);
  // le portail attend MtVenteRetailTTC ; Copilot l'appelle « Total MtVenteRetailTTC »
  const entete = lignes[0].replace('"Total MtVenteRetailTTC"', '"MtVenteRetailTTC"');
  const noms = entete.split(',').map(x => x.replace(/"/g, '').trim());
  const iJour = noms.indexOf('Jours dans Date');
  if (iJour < 0) throw new Error('colonne « Jours dans Date » absente : est-ce bien l\'export VENTESTOCKFLOW ?');
  const parJour = {};
  for (let i = 1; i < lignes.length; i++) {
    if (!lignes[i].trim()) continue;
    const j = champ(lignes[i], iJour);
    const cleJour = j.slice(6, 10) + '-' + j.slice(3, 5) + '-' + j.slice(0, 2);
    (parJour[cleJour] = parJour[cleJour] || []).push(lignes[i]);
  }
  const jours = Object.keys(parJour).sort();
  for (let i = 0; i < jours.length; i += 7) {
    const tranche = jours.slice(i, i + 7);
    let contenu = entete;
    for (const j of tranche) contenu += '\n' + parJour[j].join('\n');
    sortie.push({ json: {
      action: 'ventes_fastmag',
      fichier: (item.binary[cle].fileName || 'VENTESTOCKFLOW.csv') + ' (' + tranche[0] + ' → ' + tranche[tranche.length - 1] + ')',
      fichier_base64: Buffer.from(contenu, 'utf8').toString('base64'),
      encodage: 'utf-8'
    } });
  }
}
if (!sortie.length) throw new Error('aucune pièce jointe VENTESTOCKFLOW*.csv dans ce mail');
return sortie;

// On n'écrit que si une tranche a coincé : un dépôt réussi reste silencieux.
const erreurs = $input.all().map(x => x.json);
return [{ json: {
  sujet: 'FKB2B ventes : ' + erreurs.length + ' tranche(s) non chargée(s)',
  texte: 'Le fichier VENTESTOCKFLOW est arrivé mais le portail a refusé une partie des ventes.\n\n' + JSON.stringify(erreurs, null, 2).slice(0, 4000)
} }];
